-- RoadGuard schema starter; apply with Supabase CLI after configuring a project.
create extension if not exists pgcrypto;
create type public.incident_status as enum ('DETECTED','PENDING_REVIEW','VERIFIED','PUBLISHED','RESOLVED','REJECTED');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'commuter' check (role in ('commuter','admin')), created_at timestamptz not null default now());
create table public.video_sources (id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id), source_type text not null check(source_type in ('UPLOADED_VIDEO','DEMO_REPLAY','LIVE_STREAM','HISTORICAL_IMAGERY')), storage_path text not null, original_name text not null, created_at timestamptz not null default now());
create table public.processing_jobs (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.video_sources(id), status text not null check(status in ('QUEUED','PROCESSING','COMPLETED','FAILED','CANCELLED')), progress numeric not null default 0 check(progress between 0 and 100), error_code text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.incidents (id uuid primary key default gen_random_uuid(), hazard_type text not null, description text not null default '', latitude double precision check(latitude between -90 and 90), longitude double precision check(longitude between -180 and 180), severity text not null check(severity in ('LOW','MEDIUM','HIGH','CRITICAL')), ai_confidence numeric check(ai_confidence between 0 and 1), context_score numeric check(context_score between 0 and 1), location_accuracy_m numeric, status public.incident_status not null default 'PENDING_REVIEW', source_type text not null, created_at timestamptz not null default now(), last_verified_at timestamptz);
create index incidents_status_location on public.incidents(status, latitude, longitude);
create table public.detections (id uuid primary key default gen_random_uuid(), job_id uuid references public.processing_jobs(id), incident_id uuid references public.incidents(id), frame_second numeric not null, model_class text not null, confidence numeric not null check(confidence between 0 and 1), bbox jsonb not null, evidence_path text, created_at timestamptz not null default now());
create table public.user_reports (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), description text not null, hazard_type text not null, latitude double precision check(latitude between -90 and 90), longitude double precision check(longitude between -180 and 180), evidence_path text, status text not null default 'PENDING_REVIEW' check(status in ('PENDING_REVIEW','ACCEPTED','REJECTED')), created_at timestamptz not null default now());
create table public.incident_reviews (id uuid primary key default gen_random_uuid(), incident_id uuid not null references public.incidents(id), reviewer_id uuid not null references auth.users(id), decision public.incident_status not null, notes text not null default '', created_at timestamptz not null default now());
create table public.incident_evidence (id uuid primary key default gen_random_uuid(), incident_id uuid not null references public.incidents(id), evidence_type text not null check(evidence_type in ('FRAME','USER_REPORT','SOURCE_VIDEO')), storage_path text not null, observed_at timestamptz, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.context_logs (id uuid primary key default gen_random_uuid(), incident_id uuid not null references public.incidents(id), version text not null, inputs jsonb not null, explanation text not null, created_at timestamptz not null default now());
create table public.risk_zones (id uuid primary key default gen_random_uuid(), center_latitude double precision not null check(center_latitude between -90 and 90), center_longitude double precision not null check(center_longitude between -180 and 180), radius_m numeric not null check(radius_m > 0), verified_incidents integer not null default 0 check(verified_incidents >= 0), calculated_at timestamptz not null default now());
create table public.weather_alerts (id uuid primary key default gen_random_uuid(), provider text not null, provider_alert_id text, area jsonb not null, condition text not null, severity text not null, starts_at timestamptz not null, ends_at timestamptz not null, source_timestamp timestamptz not null, status text not null default 'ACTIVE' check(status in ('ACTIVE','EXPIRED','CANCELLED')), created_at timestamptz not null default now(), check(ends_at > starts_at));
create index weather_alerts_validity on public.weather_alerts(status, starts_at, ends_at);
create table public.automation_events (id uuid primary key default gen_random_uuid(), event_id text not null unique, event_type text not null, incident_id uuid references public.incidents(id), delivery_state text not null default 'PENDING' check(delivery_state in ('PENDING','DELIVERED','FAILED')), attempts integer not null default 0 check(attempts >= 0), last_error_code text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id uuid, before_state jsonb, after_state jsonb, created_at timestamptz not null default now());
alter table public.profiles enable row level security;
alter table public.video_sources enable row level security;
alter table public.processing_jobs enable row level security;
alter table public.incidents enable row level security;
alter table public.detections enable row level security;
alter table public.user_reports enable row level security;
alter table public.incident_reviews enable row level security;
alter table public.incident_evidence enable row level security;
alter table public.context_logs enable row level security;
alter table public.risk_zones enable row level security;
alter table public.weather_alerts enable row level security;
alter table public.automation_events enable row level security;
alter table public.audit_logs enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create policy "profiles self or admin" on public.profiles for select using (id=auth.uid() or public.is_admin());
create policy "published incidents public" on public.incidents for select using (status='PUBLISHED' or public.is_admin());
create policy "admins manage incidents" on public.incidents for update using (public.is_admin()) with check (public.is_admin());
create policy "users create reports" on public.user_reports for insert with check (auth.uid() is not null and user_id=auth.uid());
create policy "users own reports admin all" on public.user_reports for select using (user_id=auth.uid() or public.is_admin());
create policy "admins manage source data" on public.video_sources for all using (public.is_admin()) with check (public.is_admin());
create policy "admins manage jobs" on public.processing_jobs for all using (public.is_admin()) with check (public.is_admin());
create policy "admins view detections" on public.detections for select using (public.is_admin());
create policy "admins view reviews" on public.incident_reviews for select using (public.is_admin());
create policy "admins view evidence" on public.incident_evidence for select using (public.is_admin());
create policy "admins view context" on public.context_logs for select using (public.is_admin());
create policy "admins view risk zones" on public.risk_zones for select using (public.is_admin());
create policy "read current weather alerts" on public.weather_alerts for select using (status='ACTIVE' and starts_at <= now() and ends_at > now());
create policy "admins view automation events" on public.automation_events for select using (public.is_admin());
create policy "admins view audit" on public.audit_logs for select using (public.is_admin());
